using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Commands.UpdatePurchaseInvoice;public sealed class UpdatePurchaseInvoiceCommandHandler(IPurchaseInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<UpdatePurchaseInvoiceCommand,Result<PurchaseInvoiceDto>>{public async Task<Result<PurchaseInvoiceDto>>Handle(UpdatePurchaseInvoiceCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotFound);if(e.Status.ToString()!="Draft")return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotDraft);e.UpdateDetails(request.IssueDate,request.DueDate,request.SupplierInvoiceNumber,request.Notes);await db.SaveChangesAsync(cancellationToken);return Result.Success(PurchaseInvoiceDto.FromEntity(e));}}
